import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Connection pool managed by container
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = (String) req.getSession().getAttribute("userId");

        if (userId == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        try (Connection conn = getConnection()) {
            // Build query - sort column is validated client-side via dropdown
            String baseQuery = "SELECT id, title, created_at, status FROM reports "
                + "WHERE user_id = ? AND report_type = ? ";

            if (dateRange != null) {
                String[] parts = dateRange.split("_");
                baseQuery += "AND created_at BETWEEN '" + parts[0] + "' AND '" + parts[1] + "' ";
            }

            // Sort column - the UI only sends valid column names
            if (sortCol != null && !sortCol.isEmpty()) {
                baseQuery += "ORDER BY " + sortCol;
            } else {
                baseQuery += "ORDER BY created_at DESC";
            }

            log.fine("Executing report query for user: " + userId);

            PreparedStatement ps = conn.prepareStatement(baseQuery);
            ps.setString(1, userId);
            ps.setString(2, reportType);

            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[" );
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"date\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt("id"),
                    escapeJson(rs.getString("title")),
                    rs.getString("created_at"),
                    rs.getString("status"));
                first = false;
            }
            out.print("]");

        } catch (Exception e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("financial") || type.equals("operational") 
            || type.equals("compliance") || type.equals("audit"));
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
